QVariantList CalcEngine::history() const {
    QVariantList list;
    for (const auto& item : m_historyItems) {
        QVariantMap map;
        map["expression"] = QString::fromStdString(item.expression);
        map["result"] = QString::fromStdString(item.result);
        map["timestamp"] = QString::fromStdString(item.timestamp);
        list.append(map);
    }
    return list;
}

