void CalcEngine::appendDigit(const QString &digit) {
    if (m_hasError) {
        clear();
    }

    if (m_justCalculated) {
        m_expression.clear();
        m_justCalculated = false;
    }

    if (m_expression == "0" && digit != ".") {
        m_expression = digit;
    } else {
        m_expression += digit;
    }

    Q_EMIT expressionChanged();
    updateLivePreview();
}

void CalcEngine::appendOperator(const QString &op) {
    if (m_hasError) {
        m_hasError = false;
        m_errorMessage.clear();
        Q_EMIT errorChanged();
    }

    if (m_justCalculated) {
        m_expression = m_display;
        m_justCalculated = false;
    }

    std::string current = m_expression.toStdString();
    std::string newOp = op.toStdString();

    std::string updated = MathParser::handleOperatorInput(current, newOp);
    m_expression = QString::fromStdString(updated);

    Q_EMIT expressionChanged();
    updateLivePreview();
}

void CalcEngine::appendFunction(const QString &func) {
    if (m_hasError) {
        clear();
    }

    if (m_justCalculated) {
        m_expression = func + "(" + m_display + ")";
        m_justCalculated = false;
        calculate();
        return;
    }

    m_expression += func + "(";
    Q_EMIT expressionChanged();
    updateLivePreview();
}

