void CalcEngine::backspace() {
    if (m_hasError) {
        clear();
        return;
    }
    if (m_justCalculated) {
        m_justCalculated = false;
    }

    if (!m_expression.isEmpty()) {
        // If trailing space, remove operator and spaces
        while (m_expression.endsWith(' ')) {
            m_expression.chop(1);
        }
        if (!m_expression.isEmpty()) {
            m_expression.chop(1);
        }
        while (m_expression.endsWith(' ')) {
            m_expression.chop(1);
        }
    }

    if (m_expression.isEmpty()) {
        m_display = "0";
        Q_EMIT displayChanged();
    }

    Q_EMIT expressionChanged();
    updateLivePreview();
}

void CalcEngine::clear() {
    m_expression.clear();
    m_display = "0";
    m_preview.clear();
    m_hasError = false;
    m_errorMessage.clear();
    m_justCalculated = false;

    syncProgrammerFromMath(0.0);

    Q_EMIT expressionChanged();
    Q_EMIT displayChanged();
    Q_EMIT previewChanged();
    Q_EMIT errorChanged();
}

