void CalcEngine::calculate() {
    if (m_expression.trimmed().isEmpty()) return;

    std::string expr = m_expression.toStdString();
    EvalResult res = m_mathParser.evaluate(expr);

    if (res.success) {
        m_hasError = false;
        m_errorMessage.clear();
        m_display = QString::fromStdString(res.formatted);
        m_preview.clear();
        m_justCalculated = true;

        // Record history
        HistoryItem item;
        item.expression = MathParser::normalizeExpression(expr);
        item.result = res.formatted;
        item.timestamp = QDateTime::currentDateTime().toString("hh:mm:ss").toStdString();
        m_historyItems.insert(m_historyItems.begin(), item);
        if (m_historyItems.size() > 50) m_historyItems.pop_back();

        syncProgrammerFromMath(res.value);

        Q_EMIT displayChanged();
        Q_EMIT previewChanged();
        Q_EMIT historyChanged();
    } else {
        m_hasError = true;
        m_errorMessage = QString::fromStdString(res.errorMessage);
        Q_EMIT errorChanged();
    }
}

void CalcEngine::toggleSign() {
    if (m_hasError) clear();

    if (m_expression.isEmpty()) {
        m_expression = "-";
        Q_EMIT expressionChanged();
        return;
    }

    // Wrap whole expression or negate
    if (m_expression.startsWith("-(") && m_expression.endsWith(")")) {
        m_expression = m_expression.mid(2, m_expression.length() - 3);
    } else if (m_expression.startsWith("-")) {
        m_expression = m_expression.mid(1);
    } else {
        m_expression = "-(" + m_expression + ")";
    }

    Q_EMIT expressionChanged();
    updateLivePreview();
}

void CalcEngine::updateLivePreview() {
    if (m_expression.trimmed().isEmpty()) {
        m_preview.clear();
        Q_EMIT previewChanged();
        return;
    }

    EvalResult res = m_mathParser.evaluate(m_expression.toStdString());
    if (res.success) {
        m_preview = QString::fromStdString(res.formatted);
        syncProgrammerFromMath(res.value);
    } else {
        m_preview.clear();
    }
    Q_EMIT previewChanged();
}

void CalcEngine::syncProgrammerFromMath(double val) {
    if (!std::isnan(val) && !std::isinf(val)) {
        m_programmerMode.setValue(static_cast<uint64_t>(static_cast<int64_t>(val)));
        Q_EMIT programmerValuesChanged();
    }
}

void CalcEngine::syncMathFromProgrammer() {
    uint64_t val = m_programmerMode.value();
    m_expression = QString::number(val);
    m_display = m_expression;
    m_justCalculated = false;
    Q_EMIT expressionChanged();
    Q_EMIT displayChanged();
    updateLivePreview();
    Q_EMIT programmerValuesChanged();
}

