void CalcEngine::quickReciprocal() {
    if (m_hasError) clear();

    QString target = (m_justCalculated || m_expression.trimmed().isEmpty()) ? m_display : m_expression;
    if (target.trimmed().isEmpty() || target.trimmed() == "0") {
        m_hasError = true;
        m_errorMessage = "Cannot divide by zero";
        Q_EMIT errorChanged();
        return;
    }

    std::string expr = "1/(" + target.toStdString() + ")";
    EvalResult res = m_mathParser.evaluate(expr);
    if (res.success) {
        m_hasError = false;
        m_errorMessage.clear();
        m_expression = "1/(" + target + ")";
        m_display = QString::fromStdString(res.formatted);
        m_preview.clear();
        m_justCalculated = true;
        syncProgrammerFromMath(res.value);

        Q_EMIT expressionChanged();
        Q_EMIT displayChanged();
        Q_EMIT previewChanged();
        Q_EMIT errorChanged();
    } else {
        m_hasError = true;
        m_errorMessage = QString::fromStdString(res.errorMessage);
        Q_EMIT errorChanged();
    }
}

