void CalcEngine::restoreHistory(int index, bool resultOnly) {
    if (index >= 0 && index < static_cast<int>(m_historyItems.size())) {
        const auto& item = m_historyItems[index];
        if (resultOnly) {
            m_expression = QString::fromStdString(item.result);
        } else {
            m_expression = QString::fromStdString(item.expression);
        }
        m_justCalculated = false;
        Q_EMIT expressionChanged();
        updateLivePreview();
    }
}

